import{_ as e,o as t,c as r,a0 as n}from"./chunks/framework.DB31oXgM.js";const b=JSON.parse('{"title":"ADR 001: Dual Transport Layer (UDP Datagrams with WebSocket Fallback)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-transport-layer.md","filePath":"adr/001-transport-layer.md"}'),o={name:"adr/001-transport-layer.md"};function s(i,a,l,c,d,u){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="adr-001-dual-transport-layer-udp-datagrams-with-websocket-fallback" tabindex="-1">ADR 001: Dual Transport Layer (UDP Datagrams with WebSocket Fallback) <a class="header-anchor" href="#adr-001-dual-transport-layer-udp-datagrams-with-websocket-fallback" aria-label="Permalink to &quot;ADR 001: Dual Transport Layer (UDP Datagrams with WebSocket Fallback)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Real-time rollback netcode requires ultra-low latency (&lt; 16.66ms tick deadlines) and cannot tolerate Head-of-Line (HoL) blocking introduced by TCP retransmissions. However, browser environments and certain restrictive corporate NATs/firewalls restrict raw UDP datagrams without WebRTC data channels or WebSocket fallbacks.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Primary Transport (Native Clients / Dedicated Servers)</strong>: Asynchronous non-blocking UDP with 5-frame redundant input bundling ($F, F-1, F-2, F-3, F-4$) to survive packet drops without retransmission stalls.</li><li><strong>Web Client Transport</strong>: Binary WebSockets with framed datagram payloads and identical binary bitpacking to ensure cross-compatibility with the browser canvas runtime.</li><li><strong>Handshake &amp; Versioning</strong>: Versioned handshake payload enforcing protocol compatibility (<code>PROTOCOL_VERSION = 1</code>).</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Zero Head-of-Line blocking on native UDP pipes.</li><li>Transparent fallback for browser clients.</li><li>Redundant bundling increases packet payload by ~16 bytes, but eliminates the need for reliable ACK/NACK resend round-trips for transient losses.</li></ul>',9)])])}const h=e(o,[["render",s]]);export{b as __pageData,h as default};
